function packBins<T>(items: T[], sizeOf: (t:T)=>number, capacity: number): T[][] {
  const bins: T[][] = [[]];
  let used = 0;
  for (const it of items) {
    const s = sizeOf(it);
    if (used + s > capacity) { bins.push([it]); used = s; }
    else { bins[bins.length-1].push(it); used += s; }
  }
  return bins;
}
